from pathlib import Path
import re, html, json

ROOT=Path(__file__).parent
# Reuse the verified source material and embedded fonts, not the previous layouts.
scope={'__file__':str(ROOT/'build_mockups.py')}
exec((ROOT/'build_mockups.py').read_text(encoding='utf-8').split('for n,cls,title in')[0],scope)
for name in ['fonts','portrait','logo','ferris','bio','bookintro','bookmore','bookdesc','contactcopy','projects','image_data','REPO']:
    globals()[name]=scope[name]
arrow='<svg class="arrow" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M6 26 26 6M6 6h20v20" stroke="currentColor" stroke-width="2.4"/></svg>'
star='<svg class="asterisk" viewBox="0 0 100 100" aria-hidden="true"><path d="M42 0h16v31L80 9l11 11-22 22h31v16H69l22 22-11 11-22-22v31H42V69L20 91 9 80l22-22H0V42h31L9 20 20 9l22 22Z" fill="currentColor"/></svg>'
imgs=[image_data(REPO/'public/assets'/p[1],1200) for p in projects]
def link(text,to,cls='cta'):
    return f'<a class="{cls}" href="{to}">{text}{arrow}</a>'
def project_list():
    return ''.join(f'<a class="work-item" href="https://www.anastasiaguletsky.com/{p[2]}" target="_blank" rel="noopener"><div class="work-art"><img src="{im}" alt="{p[0]} campaign" loading="lazy"></div><div class="work-title"><h3>{p[0]}</h3>{arrow}</div><p>{html.escape(p[3])}</p></a>' for p,im in zip(projects,imgs))
def header():
    return f'<header class="header"><a class="brand" href="#home" aria-label="AGK home"><img src="{logo}" alt="AGK"></a><span class="header-name">Anastasia Guletsky Kelly</span><button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation"><a href="#home">Home</a><a href="#creative">Creative work</a><a href="#books">Books</a><a href="#contact">Contact{arrow}</a></nav></header>'
def splitpaths():
    return f'<div class="wayfinding"><a href="#creative"><span>Brand storytelling</span><strong>Creative work</strong>{arrow}</a><a href="#books"><span>Children’s books · Bertha, Oct 3, 2027</span><strong>Books</strong>{arrow}</a></div>'
def book_module():
    return f'<div class="book-module"><div class="book-visual"><img src="{ferris}" alt="Archival photograph of the 1893 Ferris wheel"><span class="book-date">OCT 3<br><b>2027</b></span></div><div class="book-description"><h2>BERTHA &amp;<br>THE VERY FIRST<br>BROWNIE</h2><p>{bookdesc}</p><p>Published by <a href="https://bushelandpeckbooks.com/" target="_blank" rel="noopener">Bushel &amp; Peck Books</a></p>{link('Books, schools, libraries &amp; events','#contact-books')}</div></div>'
def about():
    return f'<section class="about"><div class="about-portrait"><img src="{portrait}" alt="Anastasia Guletsky Kelly"></div><div class="about-text"><h2>Creative Director.<br>Author.<br>Friend.</h2><p>{bio}</p>{link('My resume','https://www.anastasiaguletsky.com/resume')}</div></section>'
def studio():
    return f'<section class="studio"><h2>Found Fable<br>Creative Co.</h2><div><p>Launched a creative consultancy specializing in brand voice development, content strategy and storytelling for mission-driven organizations.</p>{link('Brand &amp; creative work','#contact-creative')}{link('Found Fable Creative Co.','https://foundfablecreative.com/','text-link')}</div></section>'
def footer():
    return f'<footer><div class="footer-main"><h2>let’s chat!</h2>{link('Contact','#contact','round-link')}</div><div class="footer-links"><span>Anastasia Guletsky Kelly</span><a href="#creative">Creative work</a><a href="#books">Books</a><a href="https://foundfablecreative.com/" target="_blank" rel="noopener">Found Fable</a><a href="https://www.linkedin.com/in/anastasiaguletsky" target="_blank" rel="noopener">LinkedIn</a><a href="https://www.facebook.com/stasiamarie" target="_blank" rel="noopener">Facebook</a></div><p class="prototype-note">Design concept · Archival book image is a placeholder for forthcoming cover artwork.</p></footer>'

